with g as (select date, count(*) games from games where date between '2026-11-12' and '2026-11-23' group by 1), r as (select distinct on (as_of_date) as_of_date, run_id, created_at, (metrics->>'games')::int mg, (metrics->>'player_rows')::int pr, (metrics->>'goalie_rows')::int gr, (metrics->>'team_rows')::int tr, metrics->'data_quality'->>'skater_coverage_eligible' elig, metrics->'data_quality'->>'skater_coverage_unknown' unk, metrics->'data_quality'->>'skater_pool_projected_count_min' pmin, metrics->'execution_scope'->>'mode' mode from forge_runs where as_of_date between '2026-11-12' and '2026-11-23' and status='succeeded' order by as_of_date, created_at desc) select g.date, g.games, r.run_id, to_char(r.created_at,'MM-DD HH24:MI') created, r.mg, r.pr, r.gr, r.tr, r.elig, r.unk, r.pmin, r.mode from g left join r on r.as_of_date=g.date order by 1
